//! Source of truth is the RDF ontology; regenerate rather than patching here.

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MerkleCommit {
    pub merkle_root: String,
    pub parent: Option<Box<MerkleCommit>>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct KnowledgeWormhole {
    pub source_digest: String,
    pub target_digest: String,
}

#[derive(Debug, Clone)]
pub struct Snapshot {
    pub commit: MerkleCommit,
    pub taken_at: String,
}

impl MerkleCommit {
    pub fn genesis(merkle_root: impl Into<String>) -> Self {
        Self { merkle_root: merkle_root.into(), parent: None }
    }

    pub fn child_of(parent: MerkleCommit, merkle_root: impl Into<String>) -> Self {
        Self { merkle_root: merkle_root.into(), parent: Some(Box::new(parent)) }
    }

    /// Iterative depth walk. NOTE (Drop-glue hazard): `MerkleCommit`'s derived
    /// `Drop` recursion is a separate concern — derived drop glue recurses per
    /// link and can overflow on very long chains. Chains here are store-backed,
    /// not deep-owned: production callers hold commits behind a store that owns
    /// the parent links, so the in-process owned chain stays shallow.
    pub fn depth(&self) -> usize {
        let mut depth = 0;
        let mut cur = self.parent.as_deref();
        while let Some(parent) = cur {
            depth += 1;
            cur = parent.parent.as_deref();
        }
        depth
    }
}


